//! 🧪️ Original numerical admission matches the independent owned census and retains source storage across cancellation.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
fn inputs(law:&serde_json::Value)->(Model,SimulationConfig){let mut model=Model::default();model.zones.reserve_exact(law["zoneCapacity"].as_u64().unwrap()as usize);for(name,id)in law["zones"].as_array().unwrap().iter().zip(1..){model.zones.push(model::Zone{id:model::EntityId(id),name:name.as_str().unwrap().into(),volume_m3:40.0,multiplier:1,conditioned:true,part_of_total_floor_area:true});}let mut records=Vec::with_capacity(law["weatherCapacity"].as_u64().unwrap()as usize);for hour in 0..law["weatherRecords"].as_u64().unwrap(){records.push(site::design_day_hour(hour as u32,-10.0));}(model,SimulationConfig{weather:Some(site::WeatherData{calendar:site::WeatherCalendar::ActualDates,location:"Original".into(),latitude_deg:0.0,longitude_deg:0.0,elevation_m:0.0,time_zone_hours:0.0,records}),..Default::default()})}
fn close(owner:&mut EnergyJobAdmission,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){owner.begin_close();for index in 0..100000{if owner.terminal_is_empty(){return}let g=grant(owner.close_demands().unwrap());turn(caller,decoder,g,|cx|cx.with_original_retirement(|cx|owner.close_step(cx).map(|_|())));assert!(index<99999,"original admission closure failed to return every source");}}
#[test]
fn original_energy_admission_retains_metadata_weather_and_paid_authority(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for(cutoff,refused)in law["cancelPrefixes"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).map(|cutoff|(cutoff,false)).chain([(None,false),(None,true)]){let(model,config)=inputs(&law);let reference=EnergyNumericalCensus::observe(&model,&config).unwrap();let encoded=serde_json::to_value(reference).unwrap();for(key,value)in law["expected"].as_object().unwrap(){assert_eq!(&encoded[key],value);}let pointer=config.weather.as_ref().unwrap().records.as_ptr();let mut model=Some(model);let mut config=Some(config);let operation=Operation::new(OperationId(91001),RevisionId(7),Generation(13),31);let total=RetainedCloneGrant{maximum_items:1<<22,maximum_copy_bytes:1<<29,maximum_capacity_bytes:1<<27,maximum_release_bytes:1<<27,maximum_depth:4096};let mut caller=OriginalJobFixtureCaller::admit(operation.operation,operation.generation,total,default_now_us,u64::MAX,1<<28);let mut decoder=OriginalJobDecodeOwner::empty();let mut bounds=EnergyNumericalBounds::default();if refused{bounds.0.weather_records=0;}let mut owner=None;let d=EnergyJobAdmission::birth_demand();assert!(!turn(&mut caller,&mut decoder,RetainedCloneGrant{maximum_items:0,..grant(d)},|cx|EnergyJobAdmission::begin(operation,bounds,&mut model,&mut config,&mut owner,cx)));assert!(owner.is_none()&&model.is_some()&&config.is_some());assert!(turn(&mut caller,&mut decoder,grant(d),|cx|EnergyJobAdmission::begin(operation,bounds,&mut model,&mut config,&mut owner,cx)));let owner=owner.as_mut().unwrap();let mut foreign=OriginalJobFixtureCaller::admit(operation.operation,operation.generation,total,default_now_us,u64::MAX,1<<28);let(error,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.turn(grant(owner.demands().unwrap()),|cx|owner.step(cx)));assert!(matches!(error.unwrap_err().primary,semio_framework_job::OriginalTurnPrimary::Value(ValueError{kind:ValueRefusalKind::InvariantViolated,..})));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));foreign.retire(total);for index in 0..10000{if cutoff==Some(index)||owner.ready()||owner.rejection().is_some(){break}let d=owner.demands().unwrap();for axis in 0..5{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4=>denied.maximum_depth=0,_=>continue}assert!(!turn(&mut caller,&mut decoder,denied,|cx|owner.step(cx)));}turn(&mut caller,&mut decoder,grant(d),|cx|owner.step(cx));assert!(index<9999);}if cutoff.is_none()&&!refused{assert!(owner.ready());assert_eq!(owner.census,Some(reference));assert_eq!(owner.job.as_ref().unwrap().config.weather.as_ref().unwrap().records.as_ptr(),pointer);let mut job=None;let d=owner.demands().unwrap();assert!(turn(&mut caller,&mut decoder,grant(d),|cx|owner.take(&mut job,cx)));let mut job=job.unwrap();for index in 0..100000{if job.terminal_is_empty(){break}let d=job.original_close_demands().unwrap();turn(&mut caller,&mut decoder,grant(d),|cx|cx.with_original_retirement(|cx|job.close_step(cx).map(|_|())));assert!(index<99999);}assert!(job.terminal_is_empty());}else{let original=owner.config.as_ref().map(|config|config.weather.as_ref().unwrap().records.as_ptr()).or_else(||owner.job.as_ref().map(|job|job.config.weather.as_ref().unwrap().records.as_ptr()));assert_eq!(original,Some(pointer));}if refused{assert_eq!(format!("{:?}",owner.rejection().unwrap()),law["refusedDimension"].as_str().unwrap());assert_eq!(owner.census,Some(reference));assert!(owner.job.is_none());}close(owner,&mut caller,&mut decoder);for index in 0..100000{if decoder.terminal_is_empty(){break}let d=decoder.retirement_demands(4096).unwrap();caller.turn(grant(d),|cx|cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();assert!(index<99999);}assert!(decoder.terminal_is_empty());caller.retire(total);}
}
